'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const KEY='garimpo-platform-v1';
const stages=['found','linked','draft','approved','published'];
const labels={found:'Encontrada',linked:'Link adicionado',draft:'Em revisão',approved:'Aprovada',published:'Publicada'};
const titles={compose:'Criar post por link',overview:'Visão geral',explore:'Buscar ofertas',flow:'Meu fluxo',approved:'Prontas para postar',history:'Histórico'};
const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=s=>new Date(s).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'});
const samples=[
 {id:'demo1',title:'Organizador de bancada em bambu',category:'Casa',store:'Mercado Livre',price:59.90,oldPrice:null,stage:'found',demo:true,kind:'organizer'},
 {id:'demo2',title:'Kit de pincéis para sua rotina de beleza',category:'Beleza',store:'Shopee',price:34.90,oldPrice:null,stage:'linked',demo:true,kind:'brush'},
 {id:'demo3',title:'Kit de potes herméticos para cozinha',category:'Casa',store:'Shopee',price:79.90,oldPrice:null,stage:'draft',demo:true,kind:'jars'}
].map(o=>({...o,url:'',affiliate:'',coupon:'',notes:'',text:'',createdAt:new Date().toISOString()}));
let offers=[],view='overview',category='Todas',query='',reviewId=null;
let toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(offers));return true}catch{toast('Não foi possível salvar no navegador. Exporte um backup para preservar seus dados.');return false}}
function safeURL(value){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password?u.href:''}catch{return ''}}
function validate(o){if(!o||typeof o!=='object'||typeof o.id!=='string'||typeof o.title!=='string'||!o.title.trim()||!['Casa','Beleza'].includes(o.category)||!['Shopee','Mercado Livre'].includes(o.store)||typeof o.price!=='number'||!Number.isFinite(o.price)||o.price<=0||!stages.includes(o.stage))return false;if(o.demo!==true&&(!safeURL(o.url)||(o.affiliate&&!safeURL(o.affiliate))))return false;if(o.demo!==true&&o.stage!=='found'&&!o.affiliate)return false;if(['draft','approved','published'].includes(o.stage)&&o.demo!==true&&!String(o.text||'').trim())return false;return true}
try{const saved=localStorage.getItem(KEY);const parsed=saved?JSON.parse(saved):samples;if(!Array.isArray(parsed)||!parsed.every(validate))throw Error();offers=parsed}catch{offers=samples;setTimeout(()=>toast('Dados locais inválidos. Exemplos carregados; restaure um backup válido.'),500)}
function art(kind){const start='<svg viewBox="0 0 160 130" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">';if(kind==='brush')return start+'<ellipse cx="82" cy="117" rx="53" ry="7" fill="#e3d5ca"/><path d="M46 63h60l-8 53H54z" fill="#d5bbaa"/><ellipse cx="76" cy="63" rx="30" ry="8" fill="#c6a58e"/><path d="M58 68 47 27M74 67 72 18M88 68 99 24" stroke="#9b7c63" stroke-width="6"/><path d="M38 27q-4-19 6-21 13-3 16 17z" fill="#78685d"/><path d="M61 20Q58 1 72 2q14 0 11 18z" fill="#a98c77"/><path d="m88 25 3-12q6-14 16-6 10 7 1 23z" fill="#78685d"/><path d="M55 76h42" stroke="#e3cbb9" stroke-width="2"/></svg>';
if(kind==='jars')return start+'<ellipse cx="80" cy="118" rx="62" ry="7" fill="#deddd2"/><rect x="15" y="55" width="44" height="60" rx="8" fill="#e5e5d4" stroke="#b5b69f"/><rect x="14" y="48" width="46" height="11" rx="4" fill="#b0a387"/><rect x="64" y="36" width="46" height="79" rx="8" fill="#e9e5d4" stroke="#b5b69f"/><rect x="63" y="29" width="48" height="12" rx="4" fill="#b0a387"/><rect x="115" y="70" width="32" height="45" rx="7" fill="#e2ddc6" stroke="#b5b69f"/><rect x="114" y="64" width="34" height="10" rx="3" fill="#b0a387"/><path d="M23 69v31m50-49v49m50-16v16" stroke="#fff" stroke-width="3" opacity=".7"/></svg>';
return start+'<ellipse cx="83" cy="116" rx="63" ry="7" fill="#dedbcf"/><path d="m24 47 96-16 24 16-96 20z" fill="#d6c09a"/><path d="M24 47v47l24 22V67z" fill="#b79a70"/><path d="m48 67 96-20v47l-96 22z" fill="#cdb58d"/><path d="m58 75 74-15m-74 29 74-15m-74 29 74-15" stroke="#af9169" stroke-width="3"/><path d="M37 45V22l13-2v23m50-8V12l13-2v23" stroke="#b29873" stroke-width="5"/><path d="m35 23 66-12" stroke="#b29873" stroke-width="5"/></svg>'}
function actionLabel(o){return {found:'Adicionar meu link',linked:'Preparar texto',draft:'Revisar mensagem',approved:'Copiar para postar',published:'Ver publicação'}[o.stage]}
function card(o){return `<article class="offer"><div class="offer-visual ${o.category==='Beleza'?'beauty':''}">${art(o.kind||(o.category==='Beleza'?'brush':'organizer'))}<span class="store-badge ${o.store==='Shopee'?'shopee':''}">${esc(o.store)}</span><span class="demo-tag">${o.demo?'EXEMPLO FICTÍCIO':'ILUSTRAÇÃO'}</span></div><div class="offer-body"><div class="offer-category"><span>${esc(o.category)} · ${o.category==='Casa'?'Para o seu lar':'Seu momento de cuidado'}</span><span>♡</span></div><h3>${esc(o.title)}</h3><div class="price-row"><strong class="price">${money(o.price)}</strong>${o.oldPrice>o.price?`<span class="old-price">${money(o.oldPrice)}</span><span class="discount">−${Math.round((1-o.price/o.oldPrice)*100)}%</span>`:''}</div><span class="status ${o.stage}">${labels[o.stage]}</span><div class="offer-actions"><button data-action="advance" data-id="${esc(o.id)}">${actionLabel(o)} <span>↗</span></button><button class="edit" data-action="edit" data-id="${esc(o.id)}">Editar</button></div></div></article>`}
function heading(title,sub,eyebrow='SEU GARIMPO, ORGANIZADO'){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="subtitle">${sub}</p></div><button class="button primary" data-new>＋ Adicionar oferta</button></div>`}
function filtered(list){return list.filter(o=>(category==='Todas'||o.category===category)&&o.title.toLowerCase().includes(query.toLowerCase()))}
function filterUI(){return `<div class="section-tools"><div class="tabs">${['Todas','Casa','Beleza'].map(c=>`<button data-category="${c}" class="${c===category?'active':''}">${c}</button>`).join('')}</div><input class="search" id="filter-search" placeholder="⌕  Buscar no painel" aria-label="Buscar no painel" value="${esc(query)}"></div>`}
function renderCards(list){return filtered(list).map(card).join('')||'<div class="empty"><h3>Espaço para novos achados</h3><p>Adicione uma oferta ou ajuste os filtros para continuar.</p></div>'}
function overview(){const real=offers.filter(o=>!o.demo);return heading('Bons achados começam aqui.','Um lugar para transformar ofertas em boas recomendações.')+`<section class="hero"><div><p class="eyebrow">MENOS BAGUNÇA. MAIS GARIMPO.</p><h2>Do primeiro achado<br>à próxima boa compra.</h2><p>Encontre ofertas de casa e beleza, coloque seu link e prepare cada publicação com cuidado. Você aprova tudo.</p><button class="button" data-go="explore">Explorar ofertas <span>↗</span></button></div><div class="hero-art" aria-hidden="true"><div class="art-circle"></div><div class="art-card">${art('organizer')}Para a casa</div><div class="art-card second">${art('brush')}Para se cuidar</div><span class="spark">✧</span></div></section><section class="metrics">${[['No seu garimpo',real.filter(o=>o.stage!=='published').length,'Ofertas em andamento','⌕'],['Esperando seu link',real.filter(o=>o.stage==='found').length,'Seu toque de afiliado','↗'],['Para revisar',real.filter(o=>['linked','draft'].includes(o.stage)).length,'Textos que merecem atenção','▤'],['Prontas para postar',real.filter(o=>o.stage==='approved').length,'Com a sua aprovação','✓']].map(([name,note,sub,icon])=>`<div class="metric"><div class="metric-head"><span>${name}</span><span>${icon}</span></div><strong>${String(note).padStart(2,'0')}</strong><small>${sub}</small></div>`).join('')}</section><div class="section-heading"><h2>Seu fluxo, sem complicação</h2><button class="text-button" data-go="flow">Ver meu fluxo ↗</button></div><section class="steps">${[['Encontre','Garimpe nas duas lojas'],['Adicione seu link','Gere no portal de afiliados'],['Prepare o texto','Monte e ajuste a mensagem'],['Aprove','Confira todos os detalhes'],['Compartilhe','Publique no WhatsApp']].map(([t,s],i)=>`<div class="step"><span class="step-number">0${i+1}</span><strong>${t}</strong><small>${s}</small></div>`).join('')}</section><div class="section-heading"><h2>Na sua bancada <span style="color:#a1ad94;font-size:11px;font-weight:400">/ ofertas recentes</span></h2>${filterUI()}</div>${offers.some(o=>o.demo)?'<p class="demo-banner">✧ Os exemplos fictícios mostram como seu fluxo vai ficar. Eles não entram nos indicadores.</p>':''}<div id="card-grid" class="cards">${renderCards(offers.filter(o=>o.stage!=='published').slice().reverse().slice(0,12))}</div><div class="notice"><strong>Você tem a palavra final.</strong> Nada é enviado automaticamente. Os dados ficam neste navegador; exporte um backup para guardar suas ofertas.</div>`}
function explore(){return heading('O próximo achado está por aí.','Pesquise nas lojas e traga os produtos escolhidos para sua bancada.','HORA DE GARIMPAR')+`<section class="search-panel"><p class="eyebrow">O QUE VAMOS ENCONTRAR HOJE?</p><h2>Comece por um produto ou uma ideia.</h2><div class="chips">${['Organizador de cozinha','Potes herméticos','Jogo de cama','Kit de pincéis','Necessaire','Escova de cabelo'].map(t=>`<button class="chip" data-term="${t}">${t}</button>`).join('')}</div><label for="store-search">Produto ou palavra-chave</label><input class="search" id="store-search" placeholder="Ex.: organizador de cozinha" value="organizador de cozinha"><div class="actions"><div class="store-option"><strong>☀ Mercado Livre</strong><p>Abra a pesquisa, confira preço, vendedor e condições da oferta.</p><button class="button" data-search-store="Mercado Livre">Buscar no Mercado Livre ↗</button></div><div class="store-option"><strong>♧ Shopee</strong><p>Explore os resultados e confira avaliações, variações e cupons.</p><button class="button" data-search-store="Shopee">Buscar na Shopee ↗</button></div></div></section><div class="notice"><strong>Busca assistida, com transparência.</strong> A pesquisa abre no site da loja. Não há coleta automática nem monitoramento de preços nesta versão. Depois de escolher um produto, use “Adicionar oferta” e informe os dados conferidos.</div><div class="section-heading"><h2>Encontrou algo especial?</h2></div><section class="search-panel"><p class="subtitle">Salve o produto, o preço e o link original. Você pode adicionar seu link de afiliado depois, sem perder o achado.</p><br><button class="button primary" data-new>＋ Guardar uma oferta</button></section>`}
function flow(){return heading('Cada achado no seu lugar.','Acompanhe o caminho da oferta, sem pular sua aprovação.','DO GARIMPO À PUBLICAÇÃO')+`<div class="notice">${offers.some(o=>o.demo)?'✧ Exemplos fictícios estão identificados em cada cartão. ':''}As mudanças ficam salvas neste navegador. Clique em uma oferta para continuar.</div><div class="board">${stages.map((s,i)=>`<section class="column"><div class="column-title">0${i+1} · ${['Encontradas','Seu link','Em revisão','Aprovadas','Publicadas'][i]} <span>${offers.filter(o=>o.stage===s).length}</span></div>${offers.filter(o=>o.stage===s).map(o=>`<article class="mini"><small>${esc(o.category)} · ${esc(o.store)}${o.demo?' · EXEMPLO':''}</small><h3>${esc(o.title)}</h3><p>${money(o.price)}</p><button class="button" data-action="advance" data-id="${esc(o.id)}">${actionLabel(o)} ↗</button><button class="text-button" data-action="edit" data-id="${esc(o.id)}">Editar dados</button></article>`).join('')||'<p class="subtitle" style="font-size:10px;padding:12px">Seus próximos achados passam por aqui.</p>'}</section>`).join('')}</div>`}
function listing(history){return heading(history?'Seu histórico de boas indicações.':'Tudo certo para compartilhar.',history?'Ofertas que você marcou como publicadas manualmente.':'Mensagens revisadas e aprovadas por você.',history?'ACHADOS QUE JÁ SAÍRAM DA BANCADA':'A ÚLTIMA ETAPA É SUA')+`<div class="notice">${history?'O histórico registra sua confirmação manual; não verifica o envio no WhatsApp.':'Copie o texto aprovado, publique manualmente no WhatsApp e só então marque a oferta como publicada. Confira o preço na loja antes do envio.'}</div><div class="section-heading"><h2>${history?'Publicadas':'Fila de publicação'}</h2>${filterUI()}</div><div class="cards" id="card-grid">${renderCards(offers.filter(o=>o.stage===(history?'published':'approved')))}</div>`}
function render(){ $('#breadcrumb').textContent=titles[view];$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#nav-count').textContent=offers.filter(o=>!o.demo&&o.stage!=='published').length;$('#main').innerHTML=view==='overview'?overview():view==='explore'?explore():view==='flow'?flow():view==='compose'?compose():listing(view==='history');bind();if(view==='compose')bindComposer()}
function go(v){view=v;category='Todas';query='';render();window.scrollTo({top:0,behavior:'smooth'})}
function edit(id){const o=offers.find(o=>o.id===id);const f=$('#offer-form');f.reset();f.elements.id.value=o?.id||'';$('#editor-title').textContent=o?'Editar oferta':'Adicionar oferta';if(o)for(const name of ['title','category','store','price','oldPrice','url','affiliate','coupon','notes'])f.elements[name].value=o[name]??'';$('#editor').showModal()}
function makeText(o){return `${o.category==='Casa'?'🏡 Um achado para a sua casa!':'🌿 Um achado para sua rotina de beleza!'}\n\n${o.title}\n\n${o.oldPrice>o.price?`De ${money(o.oldPrice)} por `:''}${money(o.price)}${o.coupon?`\nCupom: ${o.coupon} (confira as condições na loja)`:''}${o.notes?`\n\n${o.notes}`:''}\n\nConfira na ${o.store}:\n${o.affiliate||'[adicione seu link de afiliado]'}\n\nLink de afiliado: posso receber comissão pela compra. Preço e disponibilidade podem mudar. Confira frete e condições na loja.`}
function review(id){const o=offers.find(o=>o.id===id);if(!o)return;if(o.stage==='found'&&!o.demo){edit(id);toast('Adicione seu link de afiliado para preparar a mensagem.');return}reviewId=id;$('#review-content').innerHTML=`<div class="review-product"><strong>${esc(o.title)}</strong>${esc(o.store)} · ${money(o.price)}${o.demo?' · EXEMPLO FICTÍCIO':''}${safeURL(o.url)?`<br><a href="${esc(safeURL(o.url))}" target="_blank" rel="noopener noreferrer">Conferir produto na loja ↗</a>`:''}</div><label for="message">Texto da publicação</label><textarea id="message" class="review-message" ${o.stage==='published'?'readonly':''}>${esc(o.text||makeText(o))}</textarea><p class="form-note">Texto montado a partir dos dados cadastrados, sem IA conectada. Edite livremente. Alterar uma mensagem aprovada exige nova aprovação.</p>${o.stage==='published'?`<p class="notice">Publicação manual registrada em ${o.publishedAt?date(o.publishedAt):'data não informada'}.</p>`:`<label class="check-label"><input type="checkbox" id="checked">Conferi preço, produto, condições e meu link de afiliado.</label>`}<div class="actions"><button class="button" id="save-draft" ${o.stage==='published'?'disabled':''}>Salvar rascunho</button><button class="button primary" id="approve" ${o.stage==='published'?'disabled':''}>Aprovar mensagem ✓</button><button class="button" id="copy" ${o.stage!=='approved'?'disabled':''}>Copiar texto</button></div>${o.stage==='approved'?'<div class="notice">Depois de copiar e enviar no seu grupo, confirme abaixo. Nenhuma mensagem será enviada por este painel.</div><label class="check-label"><input type="checkbox" id="sent">Já enviei esta mensagem manualmente no WhatsApp.</label><button class="button primary" id="mark-published">Marcar como publicada</button>':''}<div class="modal-actions"><button class="text-button danger" id="delete-offer">Excluir oferta</button><button class="button" id="close-review">Fechar</button></div>`;
$('#review').showModal();$('#close-review').onclick=()=>$('#review').close();
const text=$('#message');text.oninput=()=>{if(o.stage==='approved'){$('#copy').disabled=true;const mark=$('#mark-published');if(mark)mark.disabled=true;}$('#checked')&&($('#checked').checked=false)};
$('#save-draft').onclick=()=>{if(o.demo){toast('Este exemplo é fictício. Cadastre uma oferta real para seguir.');return}if(!text.value.trim()){toast('Escreva uma mensagem antes de salvar.');return}o.text=text.value;o.stage='draft';simpleFlowTab='prepare';o.updatedAt=new Date().toISOString();delete o.approvedAt;persist();$('#review').close();render();toast('Rascunho salvo. Revise e aprove quando estiver pronto.')};
$('#approve').onclick=()=>{if(o.demo){toast('Exemplo fictício: não pode ser aprovado. Adicione uma oferta real.');return}if(!$('#checked').checked||!text.value.trim()){toast('Confira os dados e marque a confirmação antes de aprovar.');return}if(!safeURL(o.affiliate)||!text.value.includes(o.affiliate)){toast('A mensagem precisa conter seu link de afiliado cadastrado.');return}o.text=text.value;o.stage='approved';simpleFlowTab='ready';o.approvedAt=new Date().toISOString();persist();$('#review').close();render();review(id);toast('Mensagem aprovada. Pronta para copiar e publicar manualmente.')};
$('#copy').onclick=async()=>{if(o.demo||o.stage!=='approved'||text.value!==o.text)return;try{await navigator.clipboard.writeText(o.text);toast('Texto copiado. Publique manualmente no WhatsApp.')}catch{text.focus();text.select();toast('Use Ctrl+C para copiar a mensagem selecionada.')}};
$('#mark-published')?.addEventListener('click',()=>{if(o.demo||o.stage!=='approved'||text.value!==o.text||!$('#sent').checked){toast('Confirme que você já publicou manualmente a mensagem aprovada.');return}o.stage='published';simpleFlowTab='done';o.publishedAt=new Date().toISOString();persist();$('#review').close();render();toast('Publicação manual registrada no histórico.')});
$('#delete-offer').onclick=()=>{if(!confirm('Excluir esta oferta do painel?'))return;offers=offers.filter(x=>x.id!==id);persist();$('#review').close();render();toast('Oferta excluída.')};
}
function bind(){ $$('[data-new]').forEach(b=>b.onclick=()=>edit());$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$$('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;render()});$('#filter-search')?.addEventListener('input',e=>{query=e.target.value;const list=view==='overview'?offers.filter(o=>o.stage!=='published').slice().reverse().slice(0,12):view==='explore'?offers.filter(o=>o.researchedOn):offers.filter(o=>o.stage===(view==='history'?'published':'approved'));$('#card-grid').innerHTML=renderCards(list);bindCards()});bindCards();$$('[data-term]').forEach(b=>b.onclick=()=>{$('#store-search').value=b.dataset.term;$$('[data-term]').forEach(x=>x.classList.toggle('active',x===b))});$$('[data-search-store]').forEach(b=>b.onclick=()=>{const term=$('#store-search').value.trim();if(!term){toast('Digite o produto que deseja encontrar.');return}const url=b.dataset.searchStore==='Shopee'?'https://shopee.com.br/search?keyword='+encodeURIComponent(term):'https://lista.mercadolivre.com.br/'+encodeURIComponent(term.replace(/\s+/g,'-'));window.open(url,'_blank','noopener,noreferrer')})}
function bindCards(){$$('[data-action]').forEach(b=>b.onclick=()=>{const o=offers.find(x=>x.id===b.dataset.id);if(!o)return;if(b.dataset.action==='edit')edit(o.id);else if(o.stage==='found')edit(o.id);else review(o.id)})}
$$('nav [data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));
$$('dialog>.close,dialog .modal-head .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('#offer-form .close').forEach(b=>b.onclick=()=>$('#editor').close());
$('#offer-form').onsubmit=e=>{e.preventDefault();const f=e.target;const v=Object.fromEntries(new FormData(f));const old=offers.find(o=>o.id===v.id);if(old?.demo){toast('Este cartão é apenas um exemplo. Use “Adicionar oferta” para cadastrar um produto real.');return}if(!safeURL(v.url)||(v.affiliate&&!safeURL(v.affiliate))){toast('Use links HTTPS válidos para o produto e para o afiliado.');return}const price=Number(v.price),oldPrice=v.oldPrice?Number(v.oldPrice):null;if(!Number.isFinite(price)||price<=0||(oldPrice!==null&&(!Number.isFinite(oldPrice)||oldPrice<=price))){toast('Confira os preços. O preço anterior deve ser maior que o atual, ou deixe em branco.');return}const item={...old,id:old?.id||crypto.randomUUID(),title:v.title.trim(),category:v.category,store:v.store,price,oldPrice,url:safeURL(v.url),affiliate:v.affiliate?safeURL(v.affiliate):'',coupon:v.coupon.trim(),notes:v.notes.trim(),demo:false,stage:v.affiliate?'linked':'found',text:'',createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};if(!item.title)return;if(old&&['approved','published'].includes(old.stage)&&!confirm('Editar os dados devolve a oferta à revisão e exige nova aprovação. Continuar?'))return;if(old)offers=offers.map(o=>o.id===old.id?item:o);else offers.unshift(item);persist();$('#editor').close();render();toast(item.affiliate?'Oferta salva com seu link. Já pode preparar o texto.':'Achado salvo. Adicione seu link de afiliado quando quiser.')};
$('#backup').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),offers},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='garimpo-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exportado. Guarde o arquivo em um lugar seguro.')};
$('#restore').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5000000)throw Error('Arquivo muito grande.');const data=JSON.parse(await file.text());if(data.version!==1||!Array.isArray(data.offers)||!data.offers.every(validate))throw Error('Formato de backup inválido.');if(new Set(data.offers.map(o=>o.id)).size!==data.offers.length)throw Error('O backup contém identificadores repetidos.');if(!confirm('Restaurar este backup substitui as ofertas deste navegador. Continuar?'))return;offers=data.offers;persist();render();toast('Backup restaurado.')}catch(err){toast('Não foi possível restaurar: '+err.message)}finally{e.target.value=''}};

// Merge published research without overwriting the user's links, edits or approvals.
const catalog=window.GARIMPO_CATALOG;
if(catalog&&Array.isArray(catalog.offers)){
 try{
  const seenRaw=JSON.parse(localStorage.getItem(KEY+'-catalog-seen')||'[]');
  const seen=new Set(Array.isArray(seenRaw)?seenRaw:[]);
  offers=offers.filter(o=>!o.demo);
  for(const candidate of catalog.offers){
   const item={...candidate,stage:'found',affiliate:'',coupon:'',text:'',oldPrice:null,demo:false,researchedOn:candidate.researchedOn||catalog.researchedOn,createdAt:(candidate.researchedOn||catalog.researchedOn)+'T15:00:00-03:00',sourceURL:candidate.sourceURL||candidate.url};
   if(!validate(item))continue;
   const existing=offers.find(o=>o.id===item.id);
   if(existing&&safeURL(existing.url)===safeURL(item.url)&&candidate.image){existing.image=candidate.image;existing.imageSource=candidate.imageSource;}
   if(!seen.has(item.id)&&!offers.some(o=>o.id===item.id))offers.push(item);
   seen.add(item.id);
  }
  if(persist())localStorage.setItem(KEY+'-catalog-seen',JSON.stringify([...seen]));
 }catch{toast('Não foi possível importar a curadoria. Confira o armazenamento do navegador.')}
}
const baseArt=art;
