const baseCard=card;
card=function(o){let html=baseCard(o);if(!o.researchedOn)return html;const verified=['approved','published'].includes(o.stage);const info='<div class="research-meta"><span class="reference-label">'+(verified?'Conferido por você na aprovação':'Preço de referência · confirmar na loja')+'</span><p>Pesquisa de '+esc(new Date(o.researchedOn+'T12:00:00-03:00').toLocaleDateString('pt-BR'))+' · '+esc(o.sourceAge||'fonte pública indexada')+'</p><details><summary>Condições e origem da pesquisa</summary><p>'+esc(o.priceContext||'Confira o valor atual na loja.')+'</p><a href="'+esc(safeURL(o.sourceURL))+'" target="_blank" rel="noopener noreferrer">Ver fonte da pesquisa ↗</a></details><a class="store-link" href="'+esc(safeURL(o.url))+'" target="_blank" rel="noopener noreferrer">Conferir produto na loja ↗</a></div>';html=html.replace('<span class="status ',info+'<span class="status ');return html};
const baseExplore=explore;
explore=function(){const original=baseExplore();const collection='<div class="notice"><strong>'+catalog.offers.length+' achados na curadoria · pesquisa mais recente em '+esc(new Date(catalog.researchedOn+'T12:00:00-03:00').toLocaleDateString('pt-BR'))+'.</strong> Preços de referência de páginas indexadas, sujeitos a alteração. Não há monitoramento automático. Abra o anúncio, confira o preço e gere seu próprio link de afiliado.</div><div class="section-heading"><h2>Achados da pesquisa</h2>'+filterUI()+'</div><div id="card-grid" class="cards">'+renderCards(offers.filter(o=>o.researchedOn))+'</div><div class="section-heading"><h2>Continue sua pesquisa</h2></div>';return original.replace('<section class="search-panel">',collection+'<section class="search-panel">')};
const baseText=makeText;
makeText=function(o){const text=baseText(o);return o.researchedOn?text.replace(money(o.price),'Preço de referência: '+money(o.price)):text};
const illustratedCard=card;
card=function(o){
 let html=illustratedCard(o);
 if(!/^assets\/[a-z0-9-]+\.jpg$/.test(o.image||''))return html;
 html=html.replace(/<svg\b[\s\S]*?<\/svg>/,svg=>'<img class="product-photo" src="'+esc(o.image)+'" alt="'+esc(o.title)+' — foto do anúncio original" loading="lazy" decoding="async"><span class="photo-fallback" hidden>'+svg+'</span>');
 html=html.replace('ILUSTRAÇÃO','FOTO DO ANÚNCIO');
 html=html.replace('</details>', '<p>Foto do anúncio; cores, itens ilustrados e quantidades podem variar conforme a opção escolhida.</p>'+(safeURL(o.imageSource)?'<a href="'+esc(safeURL(o.imageSource))+'" target="_blank" rel="noopener noreferrer">Ver imagem na fonte original ↗</a>':'')+'</details>');
 return html;
};
const bindOfferCards=bindCards;
bindCards=function(){bindOfferCards();$$('.product-photo').forEach(img=>{
 const fallback=()=>{img.hidden=true;const visual=img.closest('.offer-visual');visual.querySelector('.photo-fallback').hidden=false;visual.querySelector('.demo-tag').textContent='ILUSTRAÇÃO';};
 img.addEventListener('error',fallback,{once:true});
 if(img.complete&&img.naturalWidth===0)fallback();
})};
